const budgetRange=document.getElementById("budgetRange"),budgetValue=document.getElementById("budgetValue");budgetRange&&budgetValue&&budgetRange.addEventListener("input",()=>{const e=parseInt(budgetRange.value).toLocaleString("ru-RU");budgetValue.textContent=e});const swiper=document.querySelector(".calculator__slider .swiper");swiper&&swiper.addEventListener("slideChange",()=>{const e=swiper.swiper?.activeIndex||0,t=swiper.swiper?.slides.length||4,r=(e+1)/t*100,n=document.querySelector(".calculator__progress-bar span"),s=document.querySelector(".calculator__progress-text");n&&(n.style.width=`${r}%`),s&&(s.textContent=`\u0428\u0430\u0433 ${e+1} \u0438\u0437 ${t}`)});
